/* 初始化板载指示灯 GPIO。 */
void LED_Init(void)
{
    GPIO_InitTypeDef GPIO_InitStruct;

    /* 使能 GPIOE、GPIOG 时钟。 */
    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOE | RCC_AHB1Periph_GPIOG, ENABLE);

    /* PE3、PE4、PG9 配置为推挽输出，默认关闭。 */
    GPIO_InitStruct.GPIO_Pin = GPIO_Pin_3 | GPIO_Pin_4;
    GPIO_InitStruct.GPIO_Mode = GPIO_Mode_OUT;
    GPIO_InitStruct.GPIO_Speed = GPIO_Speed_25MHz;
    GPIO_InitStruct.GPIO_OType = GPIO_OType_PP;
    GPIO_InitStruct.GPIO_PuPd = GPIO_PuPd_UP;
    GPIO_Init(GPIOE, &GPIO_InitStruct);

    GPIO_InitStruct.GPIO_Pin = GPIO_Pin_9;
    GPIO_Init(GPIOG, &GPIO_InitStruct);

    GPIO_WriteBit(GPIOG, GPIO_Pin_9, Bit_SET);
    GPIO_WriteBit(GPIOE, GPIO_Pin_3 | GPIO_Pin_4, Bit_SET);
}

/* 点亮指示灯。 */
void LED_ON(void)
{
    GPIO_WriteBit(GPIOG, GPIO_Pin_9, Bit_RESET);
    GPIO_WriteBit(GPIOE, GPIO_Pin_3 | GPIO_Pin_4, Bit_RESET);
}

/* 关闭指示灯。 */
void LED_OFF(void)
{
    GPIO_WriteBit(GPIOG, GPIO_Pin_9, Bit_SET);
    GPIO_WriteBit(GPIOE, GPIO_Pin_3 | GPIO_Pin_4, Bit_SET);
}

/* 返回小智表情组数量。 */
uint8_t LED_GetXiaozhiEmojiCount(void)
{
    return XIAOZHI_EMOJI_COUNT;
}

/* 返回指定表情组的帧数；索引非法时按 0 号表情处理。 */
uint8_t LED_GetXiaozhiEmojiFrameCount(uint8_t emoji)
{
    if (emoji >= XIAOZHI_EMOJI_COUNT)
    {
        emoji = 0;
    }
    return (uint8_t)xiaozhi_emoji_frame_count[emoji];
}

/* 返回指定表情的英文名；索引非法时返回 neutral。 */
const char *LED_GetXiaozhiEmojiName(uint8_t emoji)
{
    if (emoji >= XIAOZHI_EMOJI_COUNT)
    {
        emoji = 0;
    }
    return xiaozhi_emoji_name[emoji];
}

/* 在 OLED 上显示指定表情的指定帧，帧号越界时在组内循环。 */
void LED_ShowXiaozhiEmojiFrame(uint8_t emoji, uint8_t frame)
{
    uint16_t frame_index;
    uint8_t frame_count;

    if (emoji >= XIAOZHI_EMOJI_COUNT)
    {
        emoji = 0;
    }

    frame_count = (uint8_t)xiaozhi_emoji_frame_count[emoji];
    frame %= frame_count;
    frame_index = xiaozhi_emoji_frame_offset[emoji] + frame;

    OLED_ShowPicture(0, 0, 128, 64, xiaozhi_emoji_frames[frame_index], 1);
    OLED_Refresh();
}

